def calculateBill(units):
    if units <= 100:
        return units * 3
    elif units <= 200:
        return 100 * 3 + (units - 100) * 5
    else:
        return 100 * 3 + 100 * 5 + (units - 200) * 8

def main():
    units = int(input().strip())
    bill = calculateBill(units)
    print(bill)

if __name__ == "__main__":
    main()
